/**
 * Client-side cryptography. The server never sees keys or plaintext.
 *
 *   group key      32 random bytes, generated by the group creator, shared only
 *                  through the invite link fragment (#...), stored in localStorage
 *   message/title  AES-256-GCM, random 96-bit IV, wire format base64url(iv || ct || tag)
 *   AAD            binds a ciphertext to its place: "msg|<group_id>|<message_id>" or "title"
 *   padding        plaintext is padded to a multiple of 256 bytes so length leaks little
 *   owner secret   32 random bytes per message; the server stores only sha256(secret).
 *                  Presenting the secret later is the only way to edit/delete the message.
 */

const enc = new TextEncoder();
const dec = new TextDecoder('utf-8', { fatal: true });
const PAD_BLOCK = 256;

export function toB64Url(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function fromB64Url(text: string): Uint8Array<ArrayBuffer> {
  if (!/^[A-Za-z0-9_-]*$/.test(text)) throw new Error('invalid base64url');
  const s = atob(text.replace(/-/g, '+').replace(/_/g, '/'));
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

function randomBytes(n: number): Uint8Array<ArrayBuffer> {
  return crypto.getRandomValues(new Uint8Array(n));
}

export function generateGroupKey(): string {
  return toB64Url(randomBytes(32));
}

export function isValidGroupKey(key: string): boolean {
  try {
    return fromB64Url(key).length === 32;
  } catch {
    return false;
  }
}

async function importKey(key: string): Promise<CryptoKey> {
  const raw = fromB64Url(key);
  if (raw.length !== 32) throw new Error('bad group key');
  return crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['encrypt', 'decrypt']);
}

function pad(data: Uint8Array): Uint8Array<ArrayBuffer> {
  // ISO/IEC 7816-4: 0x80 then zeros up to the block boundary.
  const len = Math.ceil((data.length + 1) / PAD_BLOCK) * PAD_BLOCK;
  const out = new Uint8Array(len);
  out.set(data);
  out[data.length] = 0x80;
  return out;
}

function unpad(data: Uint8Array): Uint8Array {
  let i = data.length - 1;
  while (i >= 0 && data[i] === 0) i--;
  if (i < 0 || data[i] !== 0x80) throw new Error('bad padding');
  return data.subarray(0, i);
}

export async function encryptText(key: string, plaintext: string, aad: string): Promise<string> {
  const iv = randomBytes(12);
  const ct = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv, additionalData: enc.encode(aad) },
    await importKey(key),
    pad(enc.encode(plaintext)),
  );
  const out = new Uint8Array(12 + ct.byteLength);
  out.set(iv);
  out.set(new Uint8Array(ct), 12);
  return toB64Url(out);
}

/** Throws if the key is wrong, the data was tampered with, or the AAD does not match. */
export async function decryptText(key: string, ciphertext: string, aad: string): Promise<string> {
  const data = fromB64Url(ciphertext);
  if (data.length < 12 + 16) throw new Error('ciphertext too short');
  const pt = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: data.subarray(0, 12), additionalData: enc.encode(aad) },
    await importKey(key),
    data.subarray(12),
  );
  return dec.decode(unpad(new Uint8Array(pt)));
}

export const messageAad = (groupId: string, messageId: string) => `msg|${groupId}|${messageId}`;
export const TITLE_AAD = 'title';

export async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', enc.encode(text));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
}

/** A fresh per-message ownership secret and the hash that is sent to the server. */
export async function newOwnerSecret(): Promise<{ secret: string; hash: string }> {
  const secret = toB64Url(randomBytes(32));
  return { secret, hash: await sha256Hex(secret) };
}
